/* store character values */
struct mf_char_ctx {
    ulong q;
    ulong * chivec;
};
typedef struct mf_char_ctx mf_char_ctx_t[1];
typedef struct mf_char_ctx mf_char2_ctx_t[2];

/* Compute the list of character values as powers of z mod p,
 * assume z has exact order ord */
void
dirichlet_chi_vec_nmod(ulong *v, slong nv, const dirichlet_group_t G,
        const dirichlet_char_t chi, ulong ord, ulong z, nmod_t mod)
{
    slong k;
    dirichlet_chi_vec_order(v, G, chi, ord, nv);
    for (k = 0; k < nv; k++)
    {
        if (v[k] == DIRICHLET_CHI_NULL)
            v[k] = 0;
        else
            v[k] = nmod_pow_ui(z, v[k], mod);
    }
}

/* store values chi(k) */
void
mf_char_ctx_init(mf_char_ctx_t ctx, const dirichlet_group_t G, slong a, ulong ord, ulong z, nmod_t mod)
{
    dirichlet_char_t chi;
    dirichlet_char_init(chi, G);
    dirichlet_char_log(chi, G, a);
    ctx->q = G->q;
    ctx->chivec = (ulong *)flint_malloc(G->q*sizeof(ulong));
    dirichlet_chi_vec_nmod(ctx->chivec, G->q, G, chi, ord, z, mod);
    dirichlet_char_clear(chi);
}
void
mf_char_ctx_clear(mf_char_ctx_t ctx)
{
    flint_free(ctx->chivec);
}
void
mf_char2_ctx_init(mf_char2_ctx_t ctx, const dirichlet_group_t G1, slong a1, const dirichlet_group_t G2, slong a2, ulong ord, ulong z, nmod_t mod)
{
    mf_char_ctx_init(ctx + 0, G1, a1, ord, z, mod);
    mf_char_ctx_init(ctx + 1, G2, a2, ord, z, mod);
}
void
mf_char2_ctx_clear(mf_char2_ctx_t ctx)
{
    mf_char_ctx_clear(ctx + 0);
    mf_char_ctx_clear(ctx + 1);
}
/* change chi -> chi^(-1) */
void
mf_char_ctx_dual(mf_char_ctx_t ctx, nmod_t mod)
{
    slong k;
    for (k = 0; k < ctx->q; k++)
        if (ctx->chivec[k])
            ctx->chivec[k] = nmod_inv(ctx->chivec[k], mod);
}
void
mf_char2_ctx_dual(mf_char2_ctx_t ctx, nmod_t mod)
{
    mf_char_ctx_dual(ctx + 0, mod);
    mf_char_ctx_dual(ctx + 1, mod);
}

/* compute Eisenstein series as Euler product */

/* fill all indices divisible by p using vector c */
void
_nmod_poly_set_euler_factor(nn_ptr z, slong len, nn_srcptr c, slong deg, slong p, nmod_t mod)
{
    slong e, pe;
    for (e = 1, pe = p; e <= deg; e++, pe *= p)
    {
        slong m, pem, r;
        for (m = 1, pem = pe; pem < len; m++, pem += pe)
            for(r = 1; r < p && pem < len; m++, pem += pe, r++)
                z[pem] = nmod_mul(z[m], c[e], mod);
    }
}
typedef void _nmod_euler_func_t(nn_ptr fp, slong deg, slong p, void * ctx, nmod_t mod);

void
_nmod_poly_euler_product(nn_ptr z, slong len, _nmod_euler_func_t factor, void * ctx, nmod_t mod)
{
    n_primes_t iter;
    slong p;
    ulong fp[30];
    n_primes_init(iter);
    z[1] = 1;
    for (p = n_primes_next(iter); p < len; p = n_primes_next(iter))
    {
        slong deg = n_flog(len, p);
        factor(fp, deg, p, ctx, mod);
        _nmod_poly_set_euler_factor(z, len, fp, deg, p, mod);
    }
    n_primes_clear(iter);
}

/* use precomputed smoothed table */
typedef struct {
    slong pe;
    slong m;
} pem_struct;
typedef pem_struct * pem_ptr;
typedef const pem_ptr pem_srcptr;

/* store complete table of smooth numbers less than len */
void
pem_init_smooth(pem_ptr tab, slong len)
{
    slong p, m;
    n_primes_t iter;
    n_primes_init(iter);
    for (m = 0; m < len; m++)
        tab[m].pe = tab[m].m = 0;
    tab[1].m = tab[1].pe = 1;
    /* could optimize */
    for (p = n_primes_next(iter); p < len; p = n_primes_next(iter))
    {
        slong pe, pem, r;
        for (pe = p; pe < len; pe *= p)
            for (m = 1, pem = pe; pem < len; m++, pem += pe)
                for(r = 1; r < p && pem < len; m++, pem += pe, r++)
                    if (tab[m].m) tab[pem].m = m, tab[pem].pe = pe;
    }
    n_primes_clear(iter);
}

/* use precomputed table of composite */
void
_nmod_poly_euler_product_precomp(nn_ptr z, slong len, _nmod_euler_func_t factor, void * ctx, pem_ptr tab, nmod_t mod)
{
    slong p, pem;
    ulong fp[30];
    n_primes_t iter;
    n_primes_init(iter);
    z[1] = 1;
    /* first expand Euler factors */
    for (p = n_primes_next(iter); p < len; p = n_primes_next(iter))
    {
        slong deg = n_flog(len, p), e, pe;
        factor(fp, deg, p, ctx, mod);
        for (e = 1, pe = p; pe < len; e++, pe *= p)
            z[pe] = fp[e];
    }
    /* then fill composite */
    for (pem = 2; pem < len; pem++)
    {
        slong m = tab[pem].m, pe = tab[pem].pe;
        if (m > 1)
            z[pem] = nmod_mul(z[m], z[pe], mod);
    }
}

/* precompute coprime decomposition k = p^e*m, p smallest prime */
struct rough {
    ulong m;
    struct rough * prev;
    struct rough * next;
};
typedef struct rough * rough_ptr;

void
pem_init_rough(pem_ptr tab, slong lim, slong len)
{
    ulong m, pe, pem, len1 = (len-1) / 2;
    rough_ptr rough, p1, m1;

    /* p=2 can be done separately */
    for (m = 3; m <= len1; m += 2)
        for (pe = 2, pem = 2*m; pem < len; pem <<= 1, pe <<= 1)
            tab[pem].pe = pe, tab[pem].m = m;

    /* now need 2-rough (ie odd) numbers up to len / 3 */
    len1 = (len-1) / 3;
    rough = flint_malloc((2 + len1/2) * sizeof(struct rough));
    rough->m = 1;
    rough->prev = NULL;
    rough->next = rough + 1;
    for (m1 = rough + 1, m = 3; m <= len1; m1++, m += 2)
    {
        m1->m = m;
        m1->prev = m1 - 1;
        m1->next = m1 + 1;
    }
    /* terminate */
    m1->m = len;
    m1->prev = m1 - 1;
    m1->next = NULL;

    for (p1 = rough + 1; p1->m <= lim; p1 = p1->next)
    {
        slong p = p1->m, pe;
        /* skip prime powers p^e up to len1 */
        for (pe = p; pe <= len1; pe *= p)
        {
            rough_ptr pe1 = rough + (pe>>1);
            pe1->next->prev = pe1->prev;
            pe1->prev->next = pe1->next;
        }
        /* then loop on p-rough numbers (p>=3) */
        for (pe = p; pe <= len1; pe *= p)
        {
            ulong lim = (len-1) / pe;
            /* loop m in p-rough numbers */
            for (m1 = p1->next; m1->m <= lim; m1 = m1->next)
            {
                slong pem = pe * m1->m;
                tab[pem].pe = pe;
                tab[pem].m = m1->m;
                /* update links to skip pem */
                if (pem >= len1) continue;
                rough_ptr pem1 = rough + (pem>>1);
                pem1->next->prev = pem1->prev;
                pem1->prev->next = pem1->next;
            }
        }
    }
    /* if lim = sqrt(len), rough now links primes > lim */
    flint_free(rough);
}

typedef struct {
    ulong n;
    ulong a;
    ulong b;
} coprime_t;
typedef coprime_t * coprime_ptr;

coprime_ptr
coprime_table_init(slong * size, slong len)
{
    slong k, n;
    coprime_ptr fac;
    pem_ptr tab = flint_malloc(len * sizeof(pem_struct));
    for (k = 0; k < len; k++)
        tab[k].pe = tab[k].m = 0;
    pem_init_rough(tab, n_sqrt(len), len);
    //flint_printf("### tab\n");
    //for (k = 0; k < len; k++)
    //    flint_printf("%ld : %ld * %ld\n",k,tab[k].pe,tab[k].m);
    fac = flint_malloc(len * sizeof(coprime_t));
    for (n = 0, k = 1; k < len; k++)
        if(tab[k].m)
            fac[n++] = (coprime_t){ .n = k, .a = tab[k].pe, .b = tab[k].m };
    flint_free(tab);
    //flint_printf("### coprime list\n");
    //for (k = 0; k < n; k++)
    //    flint_printf("%ld = %ld * %ld\n",fac[k].n,fac[k].a,fac[k].b);
    *size = n;
    fac = flint_realloc(fac, n * sizeof(coprime_t));
    return fac;
}

/* use precomputed table of composite */
void
_nmod_poly_euler_product_coprime_table(nn_ptr z, slong len, _nmod_euler_func_t factor, void * ctx, const coprime_ptr tab, slong size, nmod_t mod)
{
    slong p, k;
    ulong fp[30];
    n_primes_t iter;
    n_primes_init(iter);
    z[1] = 1;
    /* first expand Euler factors */
    for (p = n_primes_next(iter); p < len; p = n_primes_next(iter))
    {
        slong deg = n_flog(len, p), e, pe;
        factor(fp, deg, p, ctx, mod);
        for (e = 1, pe = p; pe < len; e++, pe *= p)
            z[pe] = fp[e];
    }
    /* then fill composite */
    for (k = 0; k < size; k++)
        z[tab[k].n] = nmod_mul(z[tab[k].a], z[tab[k].b], mod);
}



/* Euler factors of Eisenstein series */

/* E_2( Mod(1,N) ) as prod_p ((1-p^(-s))*(1-p^(1-s)))^(-1). Assume N prime. */
void
_nmod_euler_factor_E2_1N(nn_ptr fp, slong deg, slong p, void * ctx, nmod_t mod)
{
    long N = (long)ctx;
    if (p == N)
    {
        ulong Q[2] = { 1, mod.n - 1 };
        _nmod_poly_inv_series(fp, Q, 2, deg+1, mod);
    }
    else
    {
        /* (1-p*x)*(1-x) = p*x^2 + (-p - 1)*x + 1 */
        ulong Q[3] = { 1, mod.n - p - 1, p };
        _nmod_poly_inv_series(fp, Q, 3, deg+1, mod);
    }
}

/* Lp(E_1(chi))^-1 = ( 1-chi(p)p^(-s) ) * ( 1-p^(-s) ) */
void
_nmod_euler_factor_E1_chi(nn_ptr fp, slong deg, slong p, void * ctx_ptr, nmod_t mod)
{
    struct mf_char_ctx * ctx = (struct mf_char_ctx *)ctx_ptr;
    ulong chip = ctx->chivec[p % ctx->q];
    ulong Q[3] = { 1, mod.n - chip - 1, chip }; /* (1-chip*x)*(1-x) */
    _nmod_poly_inv_series(fp, Q, 3, deg+1, mod);
}

/* Lp(E_1(chi,psi))^-1 = ( 1-chi(p)p^(-s) ) * ( 1-psi(p)*p^(-s) ) */
void
_nmod_euler_factor_E1_chi_psi(nn_ptr fp, slong deg, slong p, void * ctx_ptr, nmod_t mod)
{
    struct mf_char_ctx * ctx = (struct mf_char_ctx *)ctx_ptr;
    ulong chip = ctx[0].chivec[p % ctx[0].q];
    ulong psip = ctx[1].chivec[p % ctx[1].q];
    ulong Q[3] = { 1, mod.n - chip - psip, nmod_mul(chip,psip,mod) };
    _nmod_poly_inv_series(fp, Q, 3, deg+1, mod);
}

typedef struct {
    slong count_euler;
    slong count_prod;
    slong cpu_euler;
    slong wall_euler;
    slong cpu_prod;
    slong wall_prod;
} mf_timer_t;

/* matrix of modular form coefficients modulo f.modp,
   one column per coefficient expressed on integral basis */
void
nmod_mat_modular_form_expansion(nmod_mat_t a, slong deg, slong len, const struct mf_eis_desc f, mf_timer_t * timer)
{
    nmod_t mod;
    dirichlet_group_t G;
    slong i, k;
    const ulong * coefs = f.coefs;
    nn_ptr g, g0, g1, g2, g12;
    mpn_ctx_t fft_ctx;
    timeit_t t;

    FLINT_ASSERT(deg <= f.degy && deg == nmod_mat_nrows(a));
    FLINT_ASSERT(len == nmod_mat_ncols(a));
    FLINT_ASSERT(n_trailing_zeros(f.modp-1) > n_clog2(len));

    nmod_mat_set_mod(a, f.modp);
    nmod_init(&mod, f.modp);
    /*
     Critical part: force mpn_mul (_nmod_poly_mul_mid_mpn_ctx)
     to use custom 50 bits prime p = mod.n
     Initialize context fft_ctx accordingly.
     */
    mpn_ctx_init(fft_ctx, mod.n);

    /* Eisenstein part (no product) */

    if (timer)
        timeit_start(t);

    g0 = _nmod_vec_init(len);
    g0[0] = 0;
    _nmod_poly_euler_product(g0, len, _nmod_euler_factor_E2_1N, (void *)f.N, mod);

    for (i = 0, g = a->entries; i < deg; g += a->stride, i++)
    {
        ulong c = nmod_set_ui(coefs[i], mod);
        _nmod_vec_scalar_mul_nmod(g, g0, len, c, mod);
    }
    _nmod_vec_clear(g0);

    if (timer)
    {
        timeit_stop(t);
        timer->count_euler += 1;
        timer->cpu_euler += t->cpu;
        timer->wall_euler += t->wall;
    }

    /* add products c[k] * E1(chi[k]) * E1(chi[k]^-1) */
    dirichlet_group_init(G, f.N);
    g1 = _nmod_vec_init(len);
    g2 = _nmod_vec_init(len);
    g12 = _nmod_vec_init(len);
    for (k = 0; k < f.nchi; k++)
    {
        mf_char_ctx_t ctx;

        /* Eisenstein expansions g1 and g2 = conj(g1) */
        if (timer)
            timeit_start(t);

        mf_char_ctx_init(ctx, G, f.chi[k], f.ord, f.z, mod);

        g1[0] = nmod_set_ui(f.E0[2*k], mod);
        _nmod_poly_euler_product(g1, len, _nmod_euler_factor_E1_chi, ctx, mod);

        mf_char_ctx_dual(ctx, mod);
        g2[0] = nmod_set_ui(f.E0[2*k+1], mod);
        _nmod_poly_euler_product(g2, len, _nmod_euler_factor_E1_chi, ctx, mod);

        mf_char_ctx_clear(ctx);

        if (timer)
        {
            timeit_stop(t);
            timer->count_euler += 2;
            timer->cpu_euler += t->cpu;
            timer->wall_euler += t->wall;
        }

        /* product g12 = g1 * g2 */
        if (timer)
            timeit_start(t);

        _nmod_poly_mul_mid_mpn_ctx(g12, 0, len, g1, len, g2, len, mod, fft_ctx);
        g12[0] = 0;

        if (timer)
        {
            timeit_stop(t);
            timer->count_prod += 1;
            timer->cpu_prod += t->cpu;
            timer->wall_prod += t->wall;
        }

        coefs += f.degy;
        for (i = 0, g = a->entries; i < deg; g += a->stride, i++)
        {
            ulong c = nmod_set_ui(coefs[i], mod);
            _nmod_vec_scalar_addmul_nmod(g, g12, len, c, mod);
        }

    }
    _nmod_vec_clear(g12);
    _nmod_vec_clear(g1);
    _nmod_vec_clear(g2);
    mpn_ctx_clear(fft_ctx);

    dirichlet_group_clear(G);
}
/* matrix of modular form coefficients modulo f.modp,
   one column per coefficient expressed on integral basis */
void
nmod_mat_modular_form_expansion_1(nmod_mat_t a, slong deg, slong len, const struct mf_eis_desc f, mf_timer_t * timer)
{
    nmod_t mod;
    dirichlet_group_t G;
    slong i, k;
    const ulong * coefs = f.coefs;
    pem_ptr tab;
    nn_ptr g, g0, g1, g2, g12;
    mpn_ctx_t fft_ctx;
    timeit_t t;

    FLINT_ASSERT(deg <= f.degy && deg == nmod_mat_nrows(a));
    FLINT_ASSERT(len == nmod_mat_ncols(a));
    FLINT_ASSERT(n_trailing_zeros(f.modp-1) > n_clog2(len));

    nmod_mat_set_mod(a, f.modp);
    nmod_init(&mod, f.modp);
    /*
     Critical part: force mpn_mul (_nmod_poly_mul_mid_mpn_ctx)
     to use custom 50 bits prime p = mod.n
     Initialize context fft_ctx accordingly.
     */
    mpn_ctx_init(fft_ctx, mod.n);

    /* initialize with E_2(1 mod N), no constant term */

    if (timer)
        timeit_start(t);

    tab = (pem_ptr)flint_malloc(len * sizeof(pem_struct));
    pem_init_smooth(tab, len);

    g0 = _nmod_vec_init(len);
    g0[0] = 0;
    _nmod_poly_euler_product_precomp(g0, len, _nmod_euler_factor_E2_1N, (void *)f.N, tab, mod);

    for (i = 0, g = a->entries; i < deg; g += a->stride, i++)
    {
        ulong c = nmod_set_ui(coefs[i], mod);
        _nmod_vec_scalar_mul_nmod(g, g0, len, c, mod);
    }
    _nmod_vec_clear(g0);

    if (timer)
    {
        timeit_stop(t);
        timer->count_euler += 1;
        timer->cpu_euler += t->cpu;
        timer->wall_euler += t->wall;
    }

    /* add products c[k] * E1(chi[k]) * E1(chi[k]^-1) */
    dirichlet_group_init(G, f.N);
    g1 = _nmod_vec_init(len);
    g2 = _nmod_vec_init(len);
    g12 = _nmod_vec_init(len);
    for (k = 0; k < f.nchi; k++)
    {
        mf_char_ctx_t ctx;

        /* Eisenstein expansions g1 and g2 = conj(g1) */
        if (timer)
            timeit_start(t);

        mf_char_ctx_init(ctx, G, f.chi[k], f.ord, f.z, mod);

        g1[0] = nmod_set_ui(f.E0[2*k], mod);
        _nmod_poly_euler_product_precomp(g1, len, _nmod_euler_factor_E1_chi, ctx, tab, mod);

        mf_char_ctx_dual(ctx, mod);
        g2[0] = nmod_set_ui(f.E0[2*k+1], mod);
        _nmod_poly_euler_product_precomp(g2, len, _nmod_euler_factor_E1_chi, ctx, tab, mod);

        mf_char_ctx_clear(ctx);

        if (timer)
        {
            timeit_stop(t);
            timer->count_euler += 2;
            timer->cpu_euler += t->cpu;
            timer->wall_euler += t->wall;
        }

        /* product g12 = g1 * g2 */
        if (timer)
            timeit_start(t);

        _nmod_poly_mul_mid_mpn_ctx(g12, 0, len, g1, len, g2, len, mod, fft_ctx);
        g12[0] = 0;

        if (timer)
        {
            timeit_stop(t);
            timer->count_prod += 1;
            timer->cpu_prod += t->cpu;
            timer->wall_prod += t->wall;
        }

        coefs += f.degy;
        for (i = 0, g = a->entries; i < deg; g += a->stride, i++)
        {
            ulong c = nmod_set_ui(coefs[i], mod);
            _nmod_vec_scalar_addmul_nmod(g, g12, len, c, mod);
        }

    }
    flint_free(tab);
    _nmod_vec_clear(g12);
    _nmod_vec_clear(g1);
    _nmod_vec_clear(g2);
    mpn_ctx_clear(fft_ctx);

    dirichlet_group_clear(G);
}

void
nmod_mat_modular_form_expansion_2(nmod_mat_t a, slong deg, slong len, const struct mf_eis_desc f, mf_timer_t * timer)
{
    nmod_t mod;
    dirichlet_group_t G;
    slong i, k, size;
    const ulong * coefs = f.coefs;
    coprime_ptr tab = NULL;
    nn_ptr g, g0, g1, g2, g12;
    mpn_ctx_t fft_ctx;
    timeit_t t;

    FLINT_ASSERT(deg <= f.degy && deg == nmod_mat_nrows(a));
    FLINT_ASSERT(len == nmod_mat_ncols(a));
    FLINT_ASSERT(n_trailing_zeros(f.modp-1) > n_clog2(len));

    nmod_mat_set_mod(a, f.modp);
    nmod_init(&mod, f.modp);
    /*
     Critical part: force mpn_mul (_nmod_poly_mul_mid_mpn_ctx)
     to use custom 50 bits prime p = mod.n
     Initialize context fft_ctx accordingly.
     */
    mpn_ctx_init(fft_ctx, mod.n);

    /* initialize with E_2(1 mod N), no constant term */

    if (timer)
        timeit_start(t);

    tab = coprime_table_init(&size, len);

    g0 = _nmod_vec_init(len);
    g0[0] = 0;
    _nmod_poly_euler_product_coprime_table(g0, len, _nmod_euler_factor_E2_1N, (void *)f.N, tab, size, mod);

    for (i = 0, g = a->entries; i < deg; g += a->stride, i++)
    {
        ulong c = nmod_set_ui(coefs[i], mod);
        _nmod_vec_scalar_mul_nmod(g, g0, len, c, mod);
    }
    _nmod_vec_clear(g0);

    if (timer)
    {
        timeit_stop(t);
        timer->count_euler += 1;
        timer->cpu_euler += t->cpu;
        timer->wall_euler += t->wall;
    }

    /* add products c[k] * E1(chi[k]) * E1(chi[k]^-1) */
    dirichlet_group_init(G, f.N);
    g1 = _nmod_vec_init(len);
    g2 = _nmod_vec_init(len);
    g12 = _nmod_vec_init(len);
    for (k = 0; k < f.nchi; k++)
    {
        mf_char_ctx_t ctx;

        /* Eisenstein expansions g1 and g2 = conj(g1) */
        if (timer)
            timeit_start(t);

        mf_char_ctx_init(ctx, G, f.chi[k], f.ord, f.z, mod);

        g1[0] = nmod_set_ui(f.E0[2*k], mod);
        _nmod_poly_euler_product_coprime_table(g1, len, _nmod_euler_factor_E1_chi, ctx, tab, size, mod);

        mf_char_ctx_dual(ctx, mod);
        g2[0] = nmod_set_ui(f.E0[2*k+1], mod);
        _nmod_poly_euler_product_coprime_table(g2, len, _nmod_euler_factor_E1_chi, ctx, tab, size, mod);

        mf_char_ctx_clear(ctx);

        if (timer)
        {
            timeit_stop(t);
            timer->count_euler += 2;
            timer->cpu_euler += t->cpu;
            timer->wall_euler += t->wall;
        }

        /* product g12 = g1 * g2 */
        if (timer)
            timeit_start(t);

        _nmod_poly_mul_mid_mpn_ctx(g12, 0, len, g1, len, g2, len, mod, fft_ctx);
        g12[0] = 0;

        if (timer)
        {
            timeit_stop(t);
            timer->count_prod += 1;
            timer->cpu_prod += t->cpu;
            timer->wall_prod += t->wall;
        }

        coefs += f.degy;
        for (i = 0, g = a->entries; i < deg; g += a->stride, i++)
        {
            ulong c = nmod_set_ui(coefs[i], mod);
            _nmod_vec_scalar_addmul_nmod(g, g12, len, c, mod);
        }

    }
    flint_free(tab);
    _nmod_vec_clear(g12);
    _nmod_vec_clear(g1);
    _nmod_vec_clear(g2);
    mpn_ctx_clear(fft_ctx);

    dirichlet_group_clear(G);
}

