/* set A to be the transpose of the last columns of Amod,
   assume Amod->c > A->r */
void
fmpz_mat_set_transpose_nmod_mat_last(fmpz_mat_t A, const nmod_mat_t Amod)
{
    slong i, j, j0;

    j0 = Amod->c - A->r;
    for (i = 0; i < Amod->r; i++)
        for (j = 0; j0 + j < Amod->c; j++)
            fmpz_set_ui_smod(fmpz_mat_entry(A, j, i),
                             nmod_mat_entry(Amod, i, j0 + j), Amod->mod.n);
}

/* set A to be the transpose of Amod, but keep only
   prime row indices (ie columns of Amod of prime index) */
void
fmpz_mat_set_transpose_nmod_mat_prime(fmpz_mat_t A, const nmod_mat_t Amod)
{
    n_primes_t iter;
    slong i, j, p;

    n_primes_init(iter);
    for (j = 0, p = n_primes_next(iter); j < A->r && p < Amod->c; j++, p = n_primes_next(iter))
        for (i = 0; i < Amod->r; i++)
            fmpz_set_ui_smod(fmpz_mat_entry(A, j, i),
                             nmod_mat_entry(Amod, i, p), Amod->mod.n);
    n_primes_clear(iter);
}

/* Rankin-Selberg product, assume small size */
void
_nmod_euler_factor_rankin_selberg_gl2(nn_ptr fp, slong deg, slong p, ulong ap, ulong bp, nmod_t mod)
{
    /* 1 - a*b*x + p*(a^2 + b^2 - 2p) * x^2 - a*b*p^2 * x^3 + p^4 * x^4 */
    ulong Q[5] = { 1, 0, 0, 0, 0 };
    ulong ab = nmod_mul(ap, bp, mod);
    Q[1] = nmod_neg(ab, mod);
    if (deg > 1)
    {
        ulong ab2,abp;
        ab2 = nmod_add(ap, bp, mod);
        ab2 = nmod_mul(ab2, ab2, mod);
        abp = 2 * nmod_add(ab, p, mod);
        Q[2] = nmod_mul(nmod_sub(ab2, abp, mod), p, mod);
        if (deg > 2)
        { 
           ulong p2 = nmod_mul(p, p, mod);
           Q[3] = nmod_mul(Q[1], p2, mod);
           Q[4] = nmod_mul(p2, p2, mod);
        }
    }
    _nmod_poly_inv_series(fp, Q, 5, deg+1, mod);
}
void
fmpz_euler_factor_rankin_selberg_gl2(fmpz *fp, slong deg, slong p, const fmpz_t a, const fmpz_t b)
{
    /* 1 - a*b*x + p*(a^2 + b^2 - 2p) * x^2 - a*b*p^2 * x^3 + p^4 * x^4 */
    fmpz Q[5];
    fmpz_init_set_ui(Q + 0, 1);
    fmpz_init(Q+1);
    fmpz_mul(Q+1, a, b); fmpz_neg(Q+1, Q+1);
    if (deg > 1)
    {
        /* a^2+b^2-2p = (a+b)^2 - 2ab -2p) */
        fmpz * ab2p = Q + 2;
        fmpz_add(ab2p, a, b);
        fmpz_mul(ab2p, ab2p, ab2p);
        fmpz_addmul_ui(ab2p, Q+1, 2);
        fmpz_sub_ui(ab2p, ab2p, 2*p);
        fmpz_mul_ui(ab2p, ab2p, p);
        if (deg > 2)
        {
            fmpz_mul2_uiui(Q+4, Q+0, p, p);
            fmpz_mul(Q+3, Q+1, Q+4);
            fmpz_mul(Q+4, Q+4, Q+4);
        }
    }
    _fmpz_poly_inv_series(fp, Q, 5, deg+1);
}

int usage(int count, const char * fname[])
{
    int i;
    flint_printf("mfcoefs [options] <level> <length>\n");
    flint_printf("where <level> is in");
    for (i = 0; i < count; i++) flint_printf(" %s,", fname[i]);
    flint_printf("\n and <length> is the number of terms to compute\n");
    flint_printf("output coefficients as a matrix, one row per coefficient a_p,");
    flint_printf(" columns indexed by an integral basis of the value field\n");
    flint_printf("options:\n");
    flint_printf(" --raw: raw flint output (matrix size followed by space separated values)\n");
    flint_printf(" --all: all coefficients a_n (default only a_p)\n");
    flint_printf(" --tail <n>: output only last <n> coefficients (implies --all)\n");
    flint_printf(" --time: time each step (implies --tail 0)\n");
    return EXIT_FAILURE;
}

int main(int argc, char * argv[])
{
    slong i, len;

    nmod_mat_t a;
    fmpz_mat_t m;
    slong count = 7;
    const char * mf_name[]       = { "11", "31", "41", "61", "71a", "71b", "131" };
    const struct mf_eis_desc *f = NULL, mf[] = { f11 , f31 , f41 , f61 , f71a , f71b , f131  };
    int opt_all = 0, opt_raw = 0, opt_time = 0, opt_smooth = 0, opt_test = 0;
    long opt_tail = -1;
    timeit_t total_time;
    mf_timer_t timer_struct, * timer = NULL;

    /* options */
    for (i = 1; i < argc;)
    {
        if (strcmp(argv[i], "--all") == 0)
            opt_all = 1, i++;
        else if (strcmp(argv[i], "--raw") == 0)
            opt_raw = 1, i++;
        else if (strcmp(argv[i], "--tail") == 0 && i + 1 < argc)
            opt_tail = atol(argv[i+1]), i +=2 ;
        else if (strcmp(argv[i], "--time") == 0)
            opt_time = 1, i++;
        else if (strcmp(argv[i], "--smooth") == 0)
            opt_smooth = 1, i++;
        else if (strcmp(argv[i], "--smooth2") == 0)
            opt_smooth = 2, i++;
        else if (strcmp(argv[i], "--test") == 0)
            opt_test = 1, i++;
        else break;
    }

    if (opt_time) {
        opt_tail = 0;
        timer = &timer_struct;
        timer->count_euler = 0;
        timer->count_prod = 0;
        timer->cpu_euler = 0;
        timer->wall_euler = 0;
        timer->cpu_prod = 0;
        timer->wall_prod = 0;
    }
    if (opt_tail >= 0) opt_all = 1;

    /* form and length */
    if (argc == i + 2)
    {
        slong j;
        for (j = 0; j < count; j++)
           if (strcmp(argv[i], mf_name[j]) == 0)
               break;
        f = mf + j;
        len = atol(argv[i+1]);
    }

    if (argc != i + 2 || len < 1 || f == NULL)
        return usage(count, mf_name);

    if (opt_test)
    {
        /* just timings */
        pem_ptr tab;

        timeit_start(total_time);
        tab = flint_malloc(len * sizeof(pem_struct));
        pem_init_smooth(tab, len);
        flint_free(tab);
        timeit_stop(total_time);
        flint_printf("total cpu = %wd ms  wall = %wd ms\n", total_time->cpu, total_time->wall);
        return 0;
    }

    timeit_start(total_time);

    nmod_mat_init(a, f->degy, len, f->modp);

    if (opt_smooth == 1)
        nmod_mat_modular_form_expansion_1(a, f->degy, len, *f, timer);
    else if (opt_smooth == 2)
        nmod_mat_modular_form_expansion_2(a, f->degy, len, *f, timer);
    else
        nmod_mat_modular_form_expansion(a, f->degy, len, *f, timer);

    timeit_stop(total_time);

    if (opt_tail != 0)
    {
        if (opt_all)
        {
            slong rows = (opt_tail > 0) ? opt_tail : len;
            fmpz_mat_init(m, rows, f->degy);
            fmpz_mat_set_transpose_nmod_mat_last(m, a);
        }
        else
        {
            slong rows = n_prime_pi(len);
            fmpz_mat_init(m, rows, f->degy);
            fmpz_mat_set_transpose_nmod_mat_prime(m, a);
        }

        nmod_mat_clear(a);

        if (opt_raw)
            fmpz_mat_print(m);
        else
            fmpz_mat_print_pretty(m);

        flint_printf("\n");

        fmpz_mat_clear(m);
    }

    if (opt_time)
    {
        flint_printf("euler (x%ld) cpu = %wd ms  wall = %wd ms\n", timer->count_euler, timer->cpu_euler, timer->wall_euler);
        flint_printf("prod  (x%ld) cpu = %wd ms  wall = %wd ms\n", timer->count_prod, timer->cpu_prod, timer->wall_prod);
        flint_printf("total cpu = %wd ms  wall = %wd ms\n", total_time->cpu, total_time->wall);
    }
}
